/* ---------- sign faces: Lilita One, Oswald, Archivo, Anton (SIL Open Font License), embedded so every device paints the same signs ---------- */
const FONT_FACES=[
  ['LDN Lilita','400',''],
  ['LDN Oswald','600',''],
  ['LDN Archivo','700',''],
  ['LDN Archivo','500',''],
  ['LDN Anton','400',''],
];
const FONTS_READY=(()=>{ try{ return Promise.all(FONT_FACES.map(([fam,wt,b])=>{ const bin=atob(b),u=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++) u[i]=bin.charCodeAt(i);
  const ff=new FontFace(fam,u.buffer,{weight:wt}); document.fonts.add(ff); return ff.load(); })).catch(()=>null); } catch(e){ return Promise.resolve(null); } })();
